CREATE PROCEDURE [dbo].[sp_Update_Sold_Items_From_Check] AS /** ## Procedure Name       *[toast].[dbo].[sp_Update_Sold_Items_From_Check]*   **Procedure Type**      *stored procedure*   **Author**              Wilson, Don < dwilson@newks.com >   **Version**             1   **Created**             20250331      ### Output    *describe the fields of the result set   (if code is in this description, block the code with three backticks on a blank line above and below the code block.   After the first tripple backtick, place the name of the language the code is written in.   See the example of this in the Parameters section above.  Follow the second tuple with a blank line.*      ### Change History   **Change Date:**            *YYYYMMDD*   **Author:**                 *Last, First < email address >*   **Version**:                ##   **Change:**   *detail change here*      -------------------     **/ BEGIN     -- SET NOCOUNT ON added to prevent extra result sets from     -- interfering with SELECT statements.     SET NOCOUNT ON;      declare          -- If this is for a table build, then Tab, if not, then Proc 	    @RunType varchar(4) = 'Proc'          -- The time the procedure begins running 	   ,@StartTime datetime = getdate()        -- The database the procedure is running in 	   ,@DBName varchar(150) = DB_NAME()        -- The name of the procedure itself 	   ,@ProcName varchar(150) = OBJECT_NAME(@@PROCID)        -- Default the error information to no error 	   ,@ErrorNumber int = 0 	   ,@ErrorMessage varchar(250) = '' 	   ,@ErrorLine int = 0             BEGIN TRY                 -- if this is a table build, perform it as a transaction         if (@RunType = 'Tab') begin transaction;  --		delete from toast.dbo.hstItem --		where storeid in (select distinct storeid from toast.dbo.hstItem_temp) --		and dateofbusiness in (select distinct dateofbusiness from toast.dbo.hstItem_temp)		  		update toast.dbo.hstitem_temp set 			DayPart = o.DayPart 		from toast.dbo.hstItem_temp i 		join toast.dbo.hstOrder o 		on i.OrderID = o.OrderID 		where i.DayPart is null  		update toast.dbo.hstCheck set 			DayPart = o.DayPart 		from toast.dbo.hstCheck i 		join toast.dbo.hstOrder o 		on i.OrderID = o.OrderID 		where i.DayPart is null  		update toast.dbo.hstItem_temp set 			StoreNum = r.StoreID 		from toast.dbo.hstItem_temp hgi 		join toast.dbo.restaurants r 		on hgi.StoreID = r.GUID 		where hgi.StoreNum is null  		update toast.dbo.hstItem_temp set 			DayPartID = r.DayPartID 		from toast.dbo.hstItem_temp hgi 		join toast.dbo.cfg_RestaurantService r 		on hgi.DayPart = r.GUID 		and hgi.StoreID = r.StoreGUID 		where hgi.DayPartID is null  		update toast.dbo.hstItem_temp set 			ParentGUID = ItemGUID 		from toast.dbo.hstItem_temp hgi 		where hgi.SubModificationID = '0' 		and ParentGUID is null  		update toast.dbo.hstItem_temp set 			ItemGUID = ModifierItemID 		from toast.dbo.hstItem_temp hgi 		where hgi.SubModificationID = '0' 		and hgi.ModificationID != '0' 		and ItemGUID is null  		update toast.dbo.hstItem_temp set 			ParentGUID = ModifierItemID, 			ItemGUID = SubModifierItemID 		from toast.dbo.hstItem_temp hgi 		where hgi.SubModificationID != '0' 		and ParentGUID is null 		and ItemGUID is null  		update toast.dbo.hstItem_temp set 			ParentID = mi.Item_PLU 		from toast.dbo.hstItem_temp hi 		join toast.dbo.cfg_menu_items mi 		on hi.ParentMLI = mi.MultiLocationId  		update toast.dbo.hstItem_temp set 			ItemID = mi.Item_PLU 		from toast.dbo.hstItem_temp hi 		join toast.dbo.cfg_menu_items mi 		on hi.MenuItemMLI = mi.MultiLocationId  		/* 		insert into toast.dbo.hstitem(DateOfBusiness, StoreID, StoreNum, OrderID, CheckID, DayPart, DayPartID, SelectionID, ParentGUID, ItemGUID, ParentID,  			ItemID, ModificationID, ModifierItemID, SubModificationID, SubModifierItemID, Deferred, PreModifier, Quantity, SalesCategoryGUID, OrderMode, Price,  			DiscPric, Tax, TaxInclusion, SystemTime, Voided, VoidDate, VoidReason, AppliedDiscountAmount)         select DateOfBusiness, StoreID, StoreNum, OrderID, CheckID, DayPart, DayPartID, SelectionID, ParentGUID, ItemGUID, ParentID, ItemID, ModificationID,  			ModifierItemID, SubModificationID, SubModifierItemID, Deferred, PreModifier, Quantity, SalesCategoryGUID, OrderMode, Price, DiscPric, Tax, TaxInclusion,  			SystemTime, Voided, VoidDate, VoidReason, AppliedDiscountAmount         from toast.dbo.hstitem_temp */ 		merge toast.dbo.hstItem i 		using toast.dbo.hstItem_temp it 		on i.StoreID = it.StoreID		 		and i.DateOfBusiness = it.DateOfBusiness 		and i.OrderID = it.OrderID 		and i.CheckID = it.CheckID 		and i.SelectionID = it.SelectionID 		and i.MenuItemMLI = it.MenuItemMLI 		and i.ModificationID = it.ModificationID 		and i.ModifierItemID = it.ModifierItemID 		and i.SubModificationID = it.SubModificationID 		and i.SubModifierItemID = it.SubModifierItemID 		and i.SalesCategoryGUID = it.SalesCategoryGUID 		when matched then update set 			i.Deferred = it.Deferred, 			i.PreModifier = it.PreModifier, 			i.Quantity = it.Quantity, 			i.SalesCategoryGUID = it.SalesCategoryGUID, 			i.OrderMode = it.OrderMode, 			i.Price = it.Price, 			i.DiscPric = it.DiscPric, 			i.Tax = it.Tax, 			i.TaxInclusion = it.TaxInclusion, 			i.SystemTime = it.SystemTime, 			i.voided = it.voided, 			i.VoidDate = it.VoidDate, 			i.VoidReason = it.VoidReason, 			i.AppliedDiscountAmount = it.AppliedDiscountAmount, 			i.ItemGUID = it.ItemGUID,			 			i.ParentMLI = it.ParentMLI, 			i.ParentID = it.ParentID, 			i.ItemID = it.ItemID, 			i.DayPart = it.DayPart, 			i.DayPartID = it.DayPartID 		when not matched by target then  			insert (DateOfBusiness, StoreID, StoreNum, OrderID, CheckID, DayPart, DaypartID, SelectionID, ParentGUID, ItemGUID, ParentID, ItemID, ModificationID, ModifierItemID, SubModifierItemID, SubModificationID, Deferred, PreModifier, Quantity, SalesCategoryGUID, OrderMode, Price, DiscPric, Tax, TaxInclusion, SystemTime, VoidDate, VoidReason, AppliedDiscountAmount, voided, MenuItemMLI, ParentMLI) 			values (it.DateOfBusiness, it.StoreID, it.StoreNum, it.OrderID, it.CheckID, it.DayPart, DaypartID, it.SelectionID, it.ParentGUID, it.ItemGUID, it.ParentID, it.ItemID, it.ModificationID, it.ModifierItemID, it.SubModifierItemID, it.SubModificationID, it.Deferred, it.PreModifier, it.Quantity, it.SalesCategoryGUID, it.OrderMode, it.Price, it.DiscPric, it.Tax, it.TaxInclusion, it.SystemTime, it.VoidDate, it.VoidReason, it.AppliedDiscountAmount, it.voided, it.MenuItemMLI, it.ParentMLI);           		truncate table toast.dbo.hstItem_temp 		/* 		update toast.dbo.hstitem 		set voided = 1 		where VoidDate != '1900-01-01'   		update toast.dbo.hstitem 		set voided = 0 		where VoidDate = '1900-01-01' 		*/          -- If the table build has no error, then commit the transaction 		if (@RunType = 'Tab') commit transaction;                          -- Log the successful completion         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName;                  END TRY     BEGIN CATCH         -- If there are errors and a transaction was started, roll it back         IF @@TRANCOUNT > 0         ROLLBACK TRANSACTION;                  -- Record the error details         set @ErrorNumber  = ERROR_NUMBER();         set @ErrorLine  = ERROR_LINE();         set @ErrorMessage  = ERROR_MESSAGE();                  -- Log the error         exec Logging.dbo.Write_Procedure_Execution              @RunType = @RunType             ,@StartTime = @StartTime             ,@DBName = @DBName             ,@ProcName = @ProcName             ,@ErrorNumber = @ErrorNumber             ,@ErrorMessage = @ErrorMessage             ,@ErrorLine = @ErrorLine;         THROW;     END CATCH END